"""S141 — the ? console: the COMMAND DECK cheatsheet + the ORIENTATION briefing.

The viewscreen had no help surface and no onboarding content anywhere. This round
adds one console, reachable two ways (the band's `?` button and the S140 `?` key),
carrying two sections:

  * COMMAND DECK — the keyboard cheatsheet, GENERATED by iterating the S140
    KEY_BINDINGS table. There is no second list to keep in step, so the cheatsheet
    cannot drift from the bindings; the mutation test below proves the generation
    by pushing a binding at runtime and expecting the extra row.
  * ORIENTATION — a getting-started briefing rendered from ORIENTATION_BRIEFING, a
    declared content STRUCTURE. Every step names the on-screen control it refers
    to, and every one of those names is DECLARED with the selector + surface it
    lives on, so the reference walk below can prove each resolves to a real node
    carrying that exact label. A primer step that stopped matching the product
    turns this suite red.

Help is read-only by nature, so the `?` button is the ONE band control that is not
applyWriteState-gated — the console must open on a view-only board, where it then
carries an extra line saying so. Nothing else in the band changes: the band-parity
test reads the shipping index.html and asserts the non-help chrome is byte-for-byte
what it was before this round.

Every test drives the SHIPPING web/static/board.js in a node vm against a mini-DOM
(no jsdom, no build step — ADR-007).
"""
import json
import os
import re
import shutil
import subprocess
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
HARNESS = os.path.join(HERE, "board_help_harness.js")
STATIC = os.path.join(HERE, "..", "static")
NODE = shutil.which("node")

STAGES = ["align", "research", "validate", "plan", "plan-review", "schedule",
          "implement", "verify", "done"]


def mission(mid, stage="align", **kw):
    m = {"id": mid, "title": "Mission " + mid, "issue": 100, "stage": stage}
    m.update(kw)
    return m


def board(columns, meta=None):
    cols = {k: [] for k in STAGES}
    cols.update(columns)
    missions = [m for v in cols.values() for m in v]
    return {"columns": cols, "missions": missions,
            "meta": meta if meta is not None else
            {"repo": "acme/repo", "adapter": "local", "mode": "read-write"}}


# The fixture board the ORIENTATION reference walk runs against: one card in every
# state the primer talks about (a standby card's ▹ START ALIGNMENT, a running
# card's ⏸ Pause, a paused card's ▶ Resume, an awaiting card's Answer ▸, and a
# verify card's ✓ Review PR ▸).
def full_board():
    return board({
        "align": [mission("a1"), mission("a2", prdPending=True)],
        "implement": [mission("i1", stage="implement", running=True),
                      mission("i2", stage="implement", paused=True)],
        "verify": [mission("v1", stage="verify", prUrl="https://x/pull/1",
                           prNumber=1),
                   mission("v2", stage="verify", awaiting=True)],
    })


VERIFY_DETAIL = {
    "id": "v1", "title": "Mission v1", "issue": 100, "stage": "verify",
    "prUrl": "https://x/pull/1", "prNumber": 1, "review": "open",
    "criteria": [{"text": "it works", "done": False}],
    "tickets": [],
}


def drive(spec):
    fd, path = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    with open(path, "w") as fh:
        json.dump(spec, fh)
    try:
        out = subprocess.check_output([NODE, HARNESS, path],
                                      stderr=subprocess.STDOUT)
        return json.loads(out)
    finally:
        os.unlink(path)


class HelpBase(unittest.TestCase):
    def run_board(self, brd=None, **spec):
        spec["board"] = brd if brd is not None else board({})
        out = drive(spec)
        self.assertEqual(out["bootErrors"], [], "board.js failed to boot")
        self.assertEqual(out["runErrors"], [], "the run raised")
        return out

    def open_help(self, how="key", **spec):
        spec["open"] = how
        return self.run_board(**spec)


# ══════════ 1. two ways in, one console; Esc is the way out ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class OpeningTest(HelpBase):

    def test_the_question_mark_key_opens_the_help_console(self):
        out = self.open_help("key")
        self.assertTrue(out["help"]["open"], "? must open a console")
        self.assertTrue(out["help"]["isHelp"], "? must open the HELP console")

    def test_the_band_button_opens_the_help_console(self):
        out = self.open_help("button")
        self.assertTrue(out["help"]["open"])
        self.assertTrue(out["help"]["isHelp"])

    def test_the_key_and_the_button_open_the_SAME_console(self):
        by_key = self.open_help("key")["help"]
        by_btn = self.open_help("button")["help"]
        for field in ("title", "sections", "rows", "steps", "intro"):
            self.assertEqual(by_key[field], by_btn[field],
                             "the ? key and the ? button must render one console")

    def test_escape_closes_the_help_console(self):
        out = self.open_help("key", keys=[{"key": "Escape"}])
        self.assertTrue(out["help"]["open"], "precondition: it opened")
        self.assertTrue(out["overlayHidden"], "Esc must close the help console")
        self.assertFalse(out["helpAfterKeys"]["open"])

    def test_the_console_opens_over_an_already_open_overlay(self):
        """? is S140's sanctioned overlaySafe exception — a captain lost inside a
        console can still ask for help without dismissing it first."""
        out = self.open_help("key", openOverlayFirst=True)
        self.assertTrue(out["help"]["isHelp"])

    def test_opening_help_opens_no_write_path(self):
        out = self.open_help("button")
        self.assertEqual(out["fetches"], [],
                         "the help console must not touch the daemon")

    def test_the_console_is_one_modal_with_one_scroll(self):
        """Built on the existing modal() scaffold — one .modal-body owns the
        scroll, both sections inside it. Not a second overlay system."""
        out = self.open_help("key")
        self.assertEqual(out["help"]["scrollHosts"], 1)
        self.assertEqual([s["id"] for s in out["help"]["sections"]],
                         ["help-deck", "help-orientation"])


# ══════════ 2. the band button ══════════

class BandButtonTest(unittest.TestCase):
    """The shipping index.html is the source of truth for the band."""

    # The topbar band EXACTLY as it shipped before S141. The help button is the
    # only thing this round adds; strip that one line and the band must be
    # byte-for-byte this.
    BAND_BEFORE_S141 = '''  <div class="frame-top topbar">
    <span class="band-block" aria-hidden="true"></span>
    <div class="brand">LCARS · <b>KANBAN</b></div>
    <span class="band-block band-grow" aria-hidden="true"></span>
    <!-- which repo is this board attached to? Filled from board.meta (S70-A). -->
    <div class="repo-meta" id="repoMeta" title="attached repository"></div>
    <!-- S139: the local main-deploy band + control. #mainDeploy renders the live
         deploy status from board.meta.mainLaunch (◐ DEPLOYING → ● MAIN LIVE →
         failed) on every render; the button opens the ▸ Deploy Main modal. -->
    <div class="main-deploy" id="mainDeploy" title="local main deploy"></div>
    <button class="btn go" id="deployMainBtn" type="button">▸ Deploy Main</button>
    <button class="btn go" id="fileBtn" type="button">▦ File Mission</button>
    <div class="conn" id="conn" title="live channel">● LIVE</div>
  </div>'''

    def setUp(self):
        with open(os.path.join(STATIC, "index.html")) as fh:
            self.html = fh.read()
        i = self.html.index('<div class="frame-top topbar">')
        close = "\n  </div>"
        j = self.html.index(close, i)
        self.band = self.html[self.html.rindex("\n", 0, i) + 1:j + len(close)]

    def test_the_band_carries_a_help_button(self):
        self.assertIn('id="helpBtn"', self.band,
                      "the yellow band must carry the ? control")

    def test_the_help_button_is_titled_for_discovery(self):
        self.assertIn('title="Help — press ?"', self.band,
                      "the tooltip must teach the key")

    def test_the_help_button_label_is_the_question_mark(self):
        m = re.search(r'<button[^>]*id="helpBtn"[^>]*>([^<]*)</button>', self.band)
        self.assertIsNotNone(m, "the help control must be a <button>")
        self.assertEqual(m.group(1), "?")

    def test_the_help_button_uses_the_btn_idiom(self):
        m = re.search(r'<button([^>]*)id="helpBtn"([^>]*)>', self.band)
        attrs = m.group(1) + m.group(2)
        self.assertIn('class="btn', attrs, "it must be a .btn like its neighbours")

    def test_the_help_button_is_not_a_write_control(self):
        """markViewOnly() disables `.btn.go` inside the board plus #deployMainBtn
        by id. A help button carrying neither survives a view-only build — which
        is the whole point (help is read-only)."""
        m = re.search(r'<button([^>]*)id="helpBtn"([^>]*)>', self.band)
        attrs = m.group(1) + m.group(2)
        self.assertNotIn("go", re.search(r'class="([^"]*)"', attrs).group(1).split(),
                         "the help button must not wear the write-control class")

    def test_the_rest_of_the_band_is_byte_identical(self):
        """Everything else in the yellow band is untouched by this round."""
        stripped = re.sub(r"\n[ ]*<button[^>]*id=\"helpBtn\"[^>]*>[^<]*</button>",
                          "", self.band)
        self.assertEqual(stripped, self.BAND_BEFORE_S141)


@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class BandRenderTest(HelpBase):

    def test_the_help_button_survives_a_view_only_board(self):
        out = self.run_board(full_board(), readonly=True)
        hb = [n for n in out["bandAfter"] if n["id"] == "helpBtn"]
        self.assertEqual(len(hb), 1)
        self.assertFalse(hb[0]["disabled"],
                         "help must work on a view-only board")

    def test_the_deploy_control_still_gates_on_a_view_only_board(self):
        """Guard on the guard: the help exemption must not have leaked into the
        band's real write control."""
        out = self.run_board(full_board(), readonly=True)
        dm = [n for n in out["bandAfter"] if n["id"] == "deployMainBtn"][0]
        self.assertTrue(dm["disabled"])

    def test_the_band_order_places_help_with_the_other_controls(self):
        out = self.run_board(board({}))
        ids = [n["id"] for n in out["band"] if n["id"]]
        self.assertEqual(ids, ["repoMeta", "mainDeploy", "deployMainBtn",
                               "fileBtn", "helpBtn", "conn"])


# ══════════ 3. the COMMAND DECK is GENERATED from KEY_BINDINGS ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class CommandDeckTest(HelpBase):

    def test_the_deck_has_one_row_per_binding(self):
        out = self.open_help("key")
        self.assertEqual(len(out["help"]["rows"]), len(out["bindings"]))

    def test_every_row_prints_its_bindings_keycaps_and_label(self):
        out = self.open_help("key")
        for row, b in zip(out["help"]["rows"], out["bindings"]):
            self.assertEqual(row["caps"], b["keys"],
                             "a row must print its binding's keycaps verbatim")
            self.assertEqual(row["label"], b["label"],
                             "a row must print its binding's label verbatim")

    def test_a_binding_added_at_runtime_renders_a_row(self):
        """The generation proof: push an entry onto KEY_BINDINGS and the deck
        grows by exactly that row — no hardcoded duplicate list exists."""
        base = len(self.open_help("key")["help"]["rows"])
        out = self.open_help("key", addBinding={
            "id": "warp", "keys": ["w"], "label": "Engage the extra thing"})
        self.assertEqual(len(out["help"]["rows"]), base + 1)
        self.assertEqual(out["help"]["rows"][-1],
                         {"caps": ["w"], "label": "Engage the extra thing"})

    def test_a_multi_keycap_binding_prints_one_kbd_per_cap(self):
        out = self.open_help("key")
        rows = {r["label"]: r for r in out["help"]["rows"]}
        arrows = [r for r in out["help"]["rows"] if r["caps"] == ["↑", "↓"]]
        self.assertTrue(arrows, "the ↑↓ binding must print two separate keycaps")
        self.assertTrue(any(r["caps"] == ["Enter", "Space"]
                            for r in out["help"]["rows"]),
                        "Enter/Space must each get their own keycap")
        self.assertTrue(rows)

    def test_the_documented_keys_all_reach_the_deck(self):
        out = self.open_help("key")
        caps = set()
        for r in out["help"]["rows"]:
            caps.update(r["caps"])
        for cap in ["?", "f", "d", "↑", "↓", "←", "→", "Enter", "Space",
                    "s", "p", "v", "l", "Esc"]:
            self.assertIn(cap, caps, "the cheatsheet is missing " + cap)

    def test_the_deck_section_reads_as_a_ships_reference(self):
        out = self.open_help("key")
        deck = [s for s in out["help"]["sections"] if s["id"] == "help-deck"][0]
        self.assertEqual(deck["title"], "COMMAND DECK")


# ══════════ 4. the ORIENTATION briefing ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class OrientationTest(HelpBase):

    def test_the_briefing_is_a_declared_structure(self):
        out = self.run_board()
        self.assertIsNotNone(out["briefing"],
                             "ORIENTATION_BRIEFING must be an exported structure")
        self.assertTrue(out["briefing"]["steps"])

    def test_every_step_has_a_title_body_and_at_least_one_control(self):
        out = self.run_board()
        for s in out["briefing"]["steps"]:
            self.assertTrue(s["id"], "each step needs a stable id")
            self.assertTrue(s["title"])
            self.assertTrue(s["body"])
            self.assertTrue(s["refs"],
                            "step '%s' names no on-screen control" % s["id"])

    def test_every_named_control_is_actually_named_in_the_prose(self):
        """The declared refs and the copy cannot drift apart: a ref's label must
        appear verbatim in the step it belongs to."""
        out = self.run_board()
        for s in out["briefing"]["steps"]:
            for ref in s["refs"]:
                self.assertIn(ref["label"], s["body"],
                              "step '%s' declares %r but never says it"
                              % (s["id"], ref["label"]))

    def test_the_briefing_renders_every_step(self):
        out = self.open_help("key")
        self.assertEqual([s["id"] for s in out["help"]["steps"]],
                         [s["id"] for s in out["briefing"]["steps"]])

    def test_the_rendered_steps_carry_the_declared_copy(self):
        out = self.open_help("key")
        for rendered, declared in zip(out["help"]["steps"],
                                      out["briefing"]["steps"]):
            self.assertEqual(rendered["title"], declared["title"])
            self.assertEqual(rendered["text"], declared["body"])

    def test_the_orientation_section_is_titled(self):
        out = self.open_help("key")
        sec = [s for s in out["help"]["sections"]
               if s["id"] == "help-orientation"][0]
        self.assertEqual(sec["title"], "ORIENTATION")

    def test_the_briefing_is_about_a_screenful(self):
        """Long enough to orient, short enough to read standing up."""
        out = self.run_board()
        words = sum(len(s["body"].split()) for s in out["briefing"]["steps"])
        self.assertGreater(words, 120, "too thin to orient anyone")
        self.assertLess(words, 500, "a briefing, not a manual")

    # ── the honesty walk: every named control resolves on a real surface ──

    def test_every_named_control_resolves_to_a_real_dom_node(self):
        out = self.run_board(full_board(), resolveRefs=True, verifyId="v1",
                             missionDetail=VERIFY_DETAIL)
        self.assertTrue(out["refs"], "the briefing named nothing to check")
        for r in out["refs"]:
            self.assertIsNone(r["error"], "%s: %s" % (r["label"], r["error"]))
            self.assertTrue(r["found"],
                            "step '%s' names %r but %s matches nothing on the %s"
                            % (r["step"], r["label"], r["selector"], r["surface"]))

    def test_every_named_control_carries_the_label_the_primer_prints(self):
        """Resolving a node is not enough — the words the captain is told to look
        for must be the words ON that control."""
        out = self.run_board(full_board(), resolveRefs=True, verifyId="v1",
                             missionDetail=VERIFY_DETAIL)
        for r in out["refs"]:
            self.assertTrue(r["labelled"],
                            "step '%s': nothing matching %s on the %s reads %r"
                            % (r["step"], r["selector"], r["surface"], r["label"]))

    def test_the_reference_walk_covers_every_surface(self):
        """Guard on the guard: if the primer stopped naming the console controls
        the walk above would pass on the band alone."""
        out = self.run_board(full_board(), resolveRefs=True, verifyId="v1",
                             missionDetail=VERIFY_DETAIL)
        surfaces = set(r["surface"] for r in out["refs"])
        for s in ("band", "board", "file-console", "launch-console",
                  "verify-console"):
            self.assertIn(s, surfaces, "no primer step names a " + s + " control")

    def test_every_stage_column_the_briefing_names_is_on_the_board(self):
        out = self.run_board(full_board(), resolveRefs=True, verifyId="v1",
                             missionDetail=VERIFY_DETAIL)
        heads = " ".join(out["refColumns"])
        for name in out["briefing"]["columns"]:
            self.assertIn(name, heads,
                          "the briefing names a column the board doesn't render: "
                          + name)

    def test_the_briefing_names_the_columns_in_board_order(self):
        out = self.run_board()
        self.assertEqual(out["briefing"]["columns"],
                         ["Align", "Research", "Validate", "Plan", "Plan Review",
                          "Schedule", "Implement", "Verify", "Done"])

    # ── theming: a ship's console, not a README ──

    def test_the_briefing_speaks_the_ships_language(self):
        out = self.run_board()
        prose = " ".join([out["briefing"]["intro"]]
                         + [s["body"] for s in out["briefing"]["steps"]])
        for word in ("Mission", "board", "Align", "Verify"):
            self.assertIn(word, prose, "the briefing never mentions " + word)

    def test_the_briefing_is_not_readme_flavoured(self):
        out = self.run_board()
        prose = (" ".join([out["briefing"]["intro"], out["briefing"]["deckIntro"]]
                          + [s["body"] for s in out["briefing"]["steps"]]))
        for banned in ("Welcome to", "getting started", "Getting Started",
                       "click here", "🚀", "Note:", "TODO"):
            self.assertNotIn(banned, prose,
                             "off-theme copy in the briefing: " + banned)


# ══════════ 5. view-only boards ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class ViewOnlyTest(HelpBase):

    def test_the_console_still_opens_on_a_view_only_board(self):
        out = self.open_help("button", brd=full_board(), readonly=True)
        self.assertTrue(out["help"]["isHelp"])

    def test_a_view_only_board_carries_the_extra_line(self):
        out = self.open_help("key", brd=full_board(), readonly=True)
        self.assertTrue(out["help"]["viewOnlyNote"],
                        "a view-only board must say the write verbs are inert")
        self.assertIn("VIEW-ONLY", out["help"]["viewOnlyNote"])

    def test_a_writable_board_carries_no_such_line(self):
        out = self.open_help("key", brd=full_board())
        self.assertIsNone(out["help"]["viewOnlyNote"],
                          "a read-write board must render byte-identically to a "
                          "board that never heard of view-only")

    def test_the_rest_of_the_console_is_unchanged_on_a_view_only_board(self):
        rw = self.open_help("key", brd=full_board())["help"]
        ro = self.open_help("key", brd=full_board(), readonly=True)["help"]
        for field in ("title", "sections", "rows", "steps", "intro"):
            self.assertEqual(rw[field], ro[field],
                             "view-only changes ONE line, not the briefing")

    def test_the_named_controls_still_resolve_on_a_view_only_board(self):
        """They are DISABLED, not absent — so the primer still points at real
        things and a view-only visitor is not being lied to."""
        out = self.run_board(full_board(), readonly=True, resolveRefs=True,
                             verifyId="v1", missionDetail=VERIFY_DETAIL)
        for r in out["refs"]:
            self.assertTrue(r["found"] and r["labelled"],
                            "%s vanished on a view-only board" % r["label"])


