# ══════════ 7. the keycap styling ══════════

class KeycapStyleTest(unittest.TestCase):
    """A cheatsheet whose keycaps look like body text isn't a command deck."""

    def setUp(self):
        with open(os.path.join(STATIC, "board.css")) as fh:
            self.css = fh.read()

    def rule(self, sel):
        i = self.css.index(sel)
        return self.css[self.css.index("{", i) + 1:self.css.index("}", i)]

    def test_keycaps_are_styled(self):
        self.assertIn(".help-console kbd", self.css,
                      "the <kbd> keycaps need LCARS styling")

    def test_the_keycap_reads_as_a_key(self):
        r = self.rule(".help-console kbd")
        self.assertIn("border", r)
        self.assertIn("border-radius", r)

    def test_the_console_uses_the_lcars_palette(self):
        r = self.rule(".help-console kbd")
        self.assertIn("var(--lcars-", r,
                      "keycaps must use the shared LCARS token set, not raw hex")

    def test_the_empty_state_is_styled(self):
        self.assertIn(".board-empty", self.css)

    # ── D5: the printed cap must be READABLE, or the cheatsheet fails at its
    #    only job. Antonio (--font-display) is a condensed display face whose
    #    lowercase `l` is a bare vertical stroke — at 11px indistinguishable
    #    from I, | and 1, on the one row that has to tell you which key to hit.

    def test_the_keycap_does_not_wear_the_condensed_display_face(self):
        r = self.rule(".help-console kbd")
        self.assertNotIn("var(--font-display)", r,
                         "a display-face keycap renders `l` as a bare stroke — "
                         "unreadable on a sheet whose job is naming keys")

    def test_the_keycap_wears_a_font_that_disambiguates_l(self):
        r = self.rule(".help-console kbd")
        self.assertIn("var(--font-mono)", r,
                      "keycaps need a face where l / I / 1 are distinct — and it "
                      "must still be a shared LCARS token, not a one-off stack")

    def test_every_keycap_is_styled_by_the_one_rule(self):
        """Guard on the guard: the caps stay a matched set. One `.help-console
        kbd` rule dresses them all — no per-key override sneaking a second look
        into the deck."""
        self.assertEqual(self.css.count(".help-console kbd"), 1)


# ══════════ 8. the honesty pass — a console that lies is worse than none ══════
#
# The S141 tester drove the shipped console against the real board and found six
# places where the copy claimed more than the product does. Every one is pinned
# here, because each is a WORDS bug in a surface whose entire value is being
# trusted: a cheatsheet row that names an action the key does not perform, or a
# primer step that walks a new captain into a screen it never mentioned, does
# more damage than no help at all. Nothing below changes behaviour — these tests
# guard the copy against silently drifting back.


@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class BindingLabelHonestyTest(HelpBase):
    """D2 — the cheatsheet prints `label` VERBATIM, so a label that overpromises
    ships as a lie in two places at once (the table and the console).

    Two of them did: `d` said "Deploy the local main build" but only OPENS the
    ▸ Deploy Main modal (which then offers CANCEL / ▸ Deploy), and `s` said
    "Start the focused mission" but only OPENS the ▶ Launch Mission console
    (CANCEL / ▶ Start Run). Neither key deploys or starts anything.
    """

    # Every binding whose run() only OPENS a surface. The key hands you a
    # console; the console's own button is what acts.
    CONSOLE_OPENERS = ("help", "file", "deploy", "start", "verify", "open")
    # …and the ones that DO act the moment they are pressed (a direct POST, or
    # focus movement). Their labels must NOT be flattened into "Open …".
    DIRECT_ACTORS = ("pause", "launch", "nav-column", "nav-across")

    def bindings(self):
        return {b["id"]: b for b in self.run_board()["bindings"]}

    def test_the_deploy_key_says_it_opens_a_console(self):
        label = self.bindings()["deploy"]["label"]
        self.assertTrue(label.lower().startswith("open"),
                        "d opens the deploy console, it does not deploy: " + label)
        self.assertIn("console", label.lower())

    def test_the_deploy_key_does_not_claim_to_deploy(self):
        label = self.bindings()["deploy"]["label"]
        self.assertIsNone(
            re.search(r"^\s*deploy\b", label, re.I),
            "the d label must not read as an imperative deploy: " + label)

    def test_the_start_key_says_it_opens_a_console(self):
        label = self.bindings()["start"]["label"]
        self.assertTrue(label.lower().startswith("open"),
                        "s opens the launch console, it does not start a run: "
                        + label)
        self.assertIn("console", label.lower())

    def test_the_start_key_does_not_claim_to_start_the_mission(self):
        label = self.bindings()["start"]["label"]
        self.assertIsNone(
            re.search(r"^\s*(start|run|engage)\b", label, re.I),
            "the s label must not promise the drive: " + label)

    def test_every_console_opening_binding_says_open(self):
        """The audit generalised. If a later round binds another key to a control
        that merely opens a screen, its label joins this list or this test."""
        b = self.bindings()
        for bid in self.CONSOLE_OPENERS:
            self.assertIn(bid, b, "binding '%s' vanished from the table" % bid)
            self.assertTrue(
                b[bid]["label"].lower().startswith("open"),
                "binding '%s' only opens a surface but its label promises more: %r"
                % (bid, b[bid]["label"]))

    def test_the_direct_action_bindings_still_say_what_they_do(self):
        """Guard on the guard: honesty is not achieved by rewording EVERY row to
        'Open …'. p, l and the arrows act on the press, and must still say so."""
        b = self.bindings()
        for bid in self.DIRECT_ACTORS:
            self.assertFalse(
                b[bid]["label"].lower().startswith("open"),
                "binding '%s' acts immediately — 'Open …' would understate it: %r"
                % (bid, b[bid]["label"]))

    def test_the_l_row_still_reads_as_a_stand_down(self):
        """S140's fix of this same class, re-pinned here so the D2 sweep cannot
        undo it."""
        b = self.bindings()["launch"]
        self.assertRegex(b["label"].lower(), r"stand down|stop")

    def test_the_cheatsheet_prints_the_corrected_labels(self):
        """The whole reason a label fix is enough: the deck renders `label`
        verbatim, so the table and the console are cured by one edit."""
        out = self.open_help("key")
        rows = {b["id"]: r for r, b in zip(out["help"]["rows"], out["bindings"])}
        self.assertIn("console", rows["deploy"]["label"].lower())
        self.assertIn("console", rows["start"]["label"].lower())


@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class VerifyStepHonestyTest(HelpBase):
    """D1 — step 5 listed three things ✓ Review PR ▸ shows as if all three were
    always there. Only the acceptance criteria are unconditional: "what was
    built" is gated on the mission carrying tickets (or a contract proof), and
    the EST → ACTUAL line only renders once the run has usage recorded against
    it. All three degraded renderings are real screens a captain meets."""

    def body(self):
        out = self.run_board()
        return [s for s in out["briefing"]["steps"] if s["id"] == "verify"][0]["body"]

    def test_the_criteria_are_named_as_the_unconditional_part(self):
        self.assertRegex(self.body(), r"acceptance criteria are always")

    def test_what_was_built_is_named_as_conditional(self):
        b = self.body()
        m = re.search(r"what was built[^.;]*", b)
        self.assertIsNotNone(m, "step 5 stopped naming the build summary")
        self.assertRegex(m.group(0), r"\bonce\b|\bwhen\b",
                         "'what was built' only renders when the run recorded "
                         "tickets — the copy must hedge it: " + m.group(0))

    def test_the_cost_comparison_is_named_as_conditional(self):
        b = self.body()
        m = re.search(r"what it actually cost[^.;]*", b)
        self.assertIsNotNone(m, "step 5 stopped naming the EST → ACTUAL line")
        self.assertRegex(m.group(0), r"\bonce\b|\bwhen\b",
                         "the cost line only renders once the run is costed — "
                         "the copy must hedge it: " + m.group(0))

    def test_the_three_sections_are_not_listed_as_one_flat_series(self):
        """The exact shape of the original lie: a bare comma-series reads as
        three guaranteed sections."""
        self.assertNotIn("criteria, what was built, and the estimate",
                         self.body())


