# ══════════ 9. help is a COVER, not a replacement ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class HelpOverAConsoleTest(HelpBase):
    """D8 — `?` is the ONE overlaySafe binding precisely so a captain lost inside
    another console can ask. Raising the help console over that console therefore
    must not DESTROY it: openHelp() went through showOverlay(), which replaces the
    stage wholesale, so `f` → type an idea → `?` → Esc landed on the BOARD with
    the typed idea gone and no warning.

    The ruling: help sits ON TOP, one deep, and closing it puts the covered
    console back — LIVE, not re-rendered (a re-render would re-read the board and
    blow the typed state away), so the field readouts below are input state."""

    IDEA = "warp core coolant is leaking on deck 12"

    def over_file(self, **spec):
        cf = {"kind": "file", "type": self.IDEA}
        cf.update(spec.pop("console", {}))
        return self.open_help("key", consoleFirst=cf, **spec)

    # ── the captain's repro, end to end ──

    def test_the_file_console_is_not_destroyed_by_the_help_console(self):
        out = self.over_file()
        self.assertEqual(out["stageBeforeHelp"]["textareas"], [self.IDEA],
                         "precondition: the idea was typed into the console")
        self.assertEqual(out["stageAtHelp"]["helps"], 1, "? must raise help")

    def test_closing_help_returns_the_file_console_not_the_board(self):
        out = self.over_file(keys=[{"key": "Escape"}])
        after = out["stageAfterClose"]
        self.assertFalse(after["hidden"],
                         "Esc over a covered console must return THAT console, "
                         "not close the overlay to the board")
        self.assertEqual(after["helps"], 0, "the help console must be gone")
        self.assertIn("▦ File New Mission", " ".join(after["heads"]))

    def test_the_typed_idea_survives_the_round_trip(self):
        out = self.over_file(keys=[{"key": "Escape"}])
        self.assertEqual(out["stageAfterClose"]["textareas"], [self.IDEA],
                         "the half-typed idea must come back intact")

    def test_the_engine_selection_survives_the_round_trip(self):
        out = self.over_file(console={"pickEngine": "copilot"},
                             keys=[{"key": "Escape"}])
        self.assertEqual(out["stageBeforeHelp"]["engine"], ["⬡ Copilot"],
                         "precondition: Copilot was picked")
        self.assertEqual(out["stageAfterClose"]["engine"], ["⬡ Copilot"],
                         "the engine picker must come back on its chosen option")

    def test_a_second_escape_then_closes_to_the_board(self):
        out = self.over_file(keys=[{"key": "Escape"}, {"key": "Escape"}])
        self.assertTrue(out["stageAfterClose"]["hidden"],
                        "one Esc dismisses help, the next closes the console")
        self.assertEqual(out["stageAfterClose"]["modals"], [])

    def test_exactly_one_console_is_on_the_stage_at_a_time(self):
        """The tester's DOM check: while help is up it is the only modal, and when
        it goes the File console is the only modal. Never two, never zero."""
        out = self.over_file(keys=[{"key": "Escape"}])
        self.assertEqual(len(out["stageAtHelp"]["modals"]), 1)
        self.assertEqual(len(out["stageAfterClose"]["modals"]), 1)
        self.assertNotIn("help-console", out["stageAfterClose"]["modals"][0])

    def test_the_cover_and_the_restore_touch_no_write_path(self):
        out = self.over_file(keys=[{"key": "Escape"}])
        self.assertEqual(out["fetches"], [],
                         "restoring a console must not re-POST or re-fetch")

    # ── the same over the mission-detail overlay ──

    def test_help_over_the_mission_detail_restores_the_detail(self):
        out = self.open_help("key", brd=full_board(), missionDetail=VERIFY_DETAIL,
                             consoleFirst={"kind": "detail", "mid": "v1"},
                             keys=[{"key": "Escape"}])
        self.assertEqual(out["stageBeforeHelp"]["modals"], ["detail-grid"],
                         "precondition: the detail overlay was open")
        self.assertEqual(out["stageAtHelp"]["helps"], 1)
        self.assertFalse(out["stageAfterClose"]["hidden"])
        self.assertEqual(out["stageAfterClose"]["modals"], ["detail-grid"],
                         "Esc must give the mission detail back")

    def test_help_over_the_align_console_restores_the_grill(self):
        out = self.open_help("key", consoleFirst={"kind": "align"},
                             keys=[{"key": "Escape"}])
        self.assertEqual(out["stageAtHelp"]["helps"], 1)
        self.assertEqual(out["stageAfterClose"]["helps"], 0)
        self.assertIn("Alignment Console", " ".join(out["stageAfterClose"]["heads"]))
        self.assertEqual(out["stageAfterClose"], out["stageBeforeHelp"],
                         "the grill must come back byte-for-byte as it was — "
                         "including the answer the captain had selected")

    # ── opened from the bare board: nothing to restore, nothing invented ──

    def test_help_from_the_bare_board_closes_straight_to_the_board(self):
        out = self.open_help("key", keys=[{"key": "Escape"}])
        self.assertTrue(out["stageAfterClose"]["hidden"],
                        "no console was covered, so Esc closes to the board")
        self.assertEqual(out["stageAfterClose"]["modals"], [],
                         "no phantom console may appear on close")

    def test_a_console_replacing_help_releases_what_help_was_holding(self):
        """The cover is one deep in BOTH directions: if some other console takes
        the stage while help is up, the console help was holding is gone for
        good — closing must reach the board, never resurrect it on top."""
        out = self.over_file(consoleDuringHelp={"kind": "file", "type": "second"},
                             closeVia="escape")
        self.assertEqual(out["stageAfterClose"]["modals"], [],
                         "no phantom console may be restored over the board")
        self.assertTrue(out["stageAfterClose"]["hidden"])

    def test_a_later_console_is_unaffected_by_an_earlier_help_visit(self):
        """Help from the bare board leaves no save behind that a LATER console's
        close could resurrect."""
        out = self.open_help("key", keys=[{"key": "Escape"}])
        self.assertEqual(out["stageAfterClose"]["helps"], 0)
        self.assertTrue(out["overlayHidden"])

    # ── one deep: help cannot be raised over help ──

    def test_pressing_help_again_does_not_stack_a_second_console(self):
        out = self.over_file(keys=[{"key": "?", "shiftKey": True}])
        self.assertEqual(out["helpAfterKeys"]["open"], True)
        self.assertEqual(out["stageAfterClose"]["helps"], 1,
                         "? over help must not stack a second help console")
        self.assertEqual(len(out["stageAfterClose"]["modals"]), 1)

    def test_pressing_help_again_does_not_lose_the_saved_console(self):
        out = self.over_file(keys=[{"key": "?", "shiftKey": True},
                                   {"key": "Escape"}])
        self.assertFalse(out["stageAfterClose"]["hidden"],
                         "the covered console must survive a second ?")
        self.assertEqual(out["stageAfterClose"]["textareas"], [self.IDEA])

    def test_two_extra_help_presses_still_restore_on_one_escape(self):
        out = self.over_file(keys=[{"key": "?", "shiftKey": True},
                                   {"key": "?", "shiftKey": True},
                                   {"key": "Escape"}])
        self.assertEqual(out["stageAfterClose"]["helps"], 0)
        self.assertEqual(out["stageAfterClose"]["textareas"], [self.IDEA])

    # ── every close route the console renders lands in the same place ──

    def _restores(self, route):
        out = self.over_file(closeVia=route)
        return out["stageAfterClose"]

    def test_the_modal_head_close_restores_the_covered_console(self):
        after = self._restores("x")
        self.assertFalse(after["hidden"])
        self.assertEqual(after["textareas"], [self.IDEA])

    def test_the_footer_close_restores_the_covered_console(self):
        after = self._restores("footer")
        self.assertFalse(after["hidden"])
        self.assertEqual(after["textareas"], [self.IDEA])

    def test_the_backdrop_click_restores_the_covered_console(self):
        after = self._restores("backdrop")
        self.assertFalse(after["hidden"])
        self.assertEqual(after["textareas"], [self.IDEA])

    def test_every_close_route_restores_identically(self):
        routes = ["escape", "x", "footer", "backdrop"]
        seen = [self._restores(r) for r in routes]
        for route, after in zip(routes[1:], seen[1:]):
            self.assertEqual(after, seen[0],
                             "close route %r must restore like Escape" % route)

    def test_every_close_route_still_closes_help_opened_from_the_board(self):
        for route in ("escape", "x", "footer", "backdrop"):
            out = self.open_help("key", closeVia=route)
            self.assertTrue(out["stageAfterClose"]["hidden"],
                            "%s must close help to the board" % route)

    def test_the_captains_place_in_the_console_comes_back_too(self):
        """Tabbed onto a control inside the console (a non-typing target, so ?
        fires) — lifting the subtree drops focus to the page, so the restore
        hands it back. S140 exists for the keyboard captain."""
        out = self.over_file(console={"focusSel": ".modal-foot .btn"},
                             keys=[{"key": "Escape"}])
        self.assertIsNotNone(out["stageBeforeHelp"]["focus"],
                             "precondition: focus was on a console control")
        self.assertEqual(out["stageAfterClose"]["focus"],
                         out["stageBeforeHelp"]["focus"],
                         "the focused control must be focused again on restore")

    # ── the S140 guards are untouched by any of this ──

    def test_the_question_mark_still_does_nothing_inside_the_idea_box(self):
        """GUARD 1: focus still in the textarea ⇒ the keystroke is the captain
        typing a question mark, not asking for help."""
        out = self.over_file(console={"keepFocus": True})
        self.assertFalse(out["help"]["isHelp"],
                         "? typed into a field must not open the console")
        self.assertEqual(out["stageAtHelp"]["textareas"], [self.IDEA])


# ══════════ 9. the cover must not kill what it covers ══════════
#
# The second tester pass found the D8 cover's own defect: it saved the covered
# console by DETACHING its subtree. State survived — but every live loop inside a
# detached console self-cancels on `document.body.contains(node) === false`, and
# the restore re-attaches nodes while restarting nothing. Two real screens died
# that way, and any future loop would have joined them. The cure is structural:
# the covered console stays IN the document and is merely hidden, so a
# self-cancelling interval never sees itself detached and the whole class goes.

# A mission mid-run: its detail header carries the "Active …" readout, which ticks
# once a second off an interval guarded by document.body.contains().
RUNNING_DETAIL = {
    "id": "i1", "title": "Mission i1", "issue": 100, "stage": "implement",
    "running": True, "activeSeconds": 120, "criteria": [], "tickets": [],
}


def running_board():
    return board({"implement": [mission("i1", stage="implement", running=True)]})


# A Verify console mid-launch: launchAffordance polls launch.json every 1.5s
# through the same contains() guard until the launch resolves.
def verify_detail(launch):
    d = dict(VERIFY_DETAIL)
    d["launch"] = launch
    return d


def verify_board():
    return board({"verify": [mission("v1", stage="verify",
                                     prUrl="https://x/pull/1", prNumber=1)]})


def active_seconds(readout):
    """'Active 2m 6s' → 126. None when the readout is absent."""
    if not readout:
        return None
    total, m = 0, re.findall(r"(\d+)([hms])", readout)
    for value, unit in m:
        total += int(value) * {"h": 3600, "m": 60, "s": 1}[unit]
    return total if m else None


@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class CoverKeepsLiveLoopsRunningTest(HelpBase):
    """D-A — consult `?` over a live console for six seconds and the console
    underneath must come back LIVE, not embalmed. The clock a captain reads to
    judge a run, and the launch panel they watch spin up an app, are both loops
    the cover has to leave alone."""

    # ── the mission detail's Active clock ──

    def cover_the_detail(self, ms):
        return self.open_help("key", brd=running_board(),
                              missionDetail=RUNNING_DETAIL,
                              consoleFirst={"kind": "detail", "mid": "i1"},
                              advance=ms, closeVia="escape")

    def test_the_detail_clock_is_live_before_the_cover(self):
        """Precondition: the readout exists and a timer is driving it."""
        out = self.cover_the_detail(0)
        self.assertEqual(active_seconds(out["liveBeforeHelp"]["clock"]), 120,
                         "the detail must open on the server's 120s total")
        self.assertGreater(out["liveBeforeHelp"]["timers"], 1,
                           "precondition: the detail armed a tick interval of "
                           "its own (the board's safety poll is the other one)")

    def test_the_clock_keeps_ticking_while_help_covers_it(self):
        """The defect exactly: six seconds under `?`, and the clock must have
        counted them. Detaching the console self-cancels the interval, so the
        readout comes back frozen at its pre-cover value — permanently six
        seconds behind a mission that never stopped running."""
        out = self.cover_the_detail(6000)
        self.assertEqual(active_seconds(out["liveAfterClose"]["clock"]), 126,
                         "a 6s cover must cost the clock nothing: it read %r"
                         % out["liveAfterClose"]["clock"])

    def test_the_covered_clock_is_still_running_mid_cover(self):
        """Not just correct on the way out — never stopped. The readout is
        advancing WHILE help is on screen."""
        out = self.cover_the_detail(6000)
        self.assertEqual(active_seconds(out["liveUnderCover"]["clock"]), 126,
                         "the covered console's clock must tick under the cover")

    def test_the_cover_cancels_none_of_the_consoles_timers(self):
        """The general case the tester flagged: restore re-attaches nodes but
        restarts nothing, so ANY live loop in a covered console dies. Count them
        — the cover must leave the loop inventory untouched."""
        out = self.cover_the_detail(6000)
        self.assertEqual(out["liveAfterClose"]["timers"],
                         out["liveBeforeHelp"]["timers"],
                         "a timer that self-cancelled under the cover is a loop "
                         "the restore will never bring back")

    def test_the_covered_console_never_leaves_the_document(self):
        """Why the whole class is cured rather than patched loop by loop: a
        hidden element is still document.body.contains(...), so every
        self-cancelling guard in there keeps passing."""
        out = self.cover_the_detail(0)
        self.assertIsNotNone(out["liveAtHelp"]["clock"],
                             "the covered console must stay in the document — "
                             "detaching it is what kills its loops")

    def test_the_detail_still_leaks_no_timer_when_it_finally_closes(self):
        """Guard on the cure: keeping the loops alive must not turn into leaking
        them. The second Escape closes the detail for real, and clearDetailTimers
        empties the register."""
        out = self.open_help("key", brd=running_board(),
                             missionDetail=RUNNING_DETAIL,
                             consoleFirst={"kind": "detail", "mid": "i1"},
                             advance=6000,
                             keys=[{"key": "Escape"}, {"key": "Escape"}])
        self.assertTrue(out["stageAfterClose"]["hidden"])
        self.assertEqual(out["detailTimers"], 0,
                         "closing the detail must leave DETAIL_TIMERS empty")

    # ── the Verify console's launch poll ──

    def cover_the_launch(self, ms, resolved):
        return self.open_help("key", brd=verify_board(),
                              missionDetail=verify_detail({"status": "launching"}),
                              consoleFirst={"kind": "verify", "mid": "v1"},
                              missionDetailDuring=verify_detail(resolved),
                              advance=ms, closeVia="escape")

    RESOLVED = {"status": "running", "target": "the app",
                "url": "http://127.0.0.1:5173"}

    def test_the_launch_panel_is_polling_before_the_cover(self):
        out = self.cover_the_launch(0, self.RESOLVED)
        self.assertIn("Launching the app…", out["liveBeforeHelp"]["launch"] or "",
                      "precondition: the panel is mid-launch and polling")

    def test_a_launch_that_resolves_under_the_cover_is_still_seen(self):
        """A captain who consults `?` mid-launch must not be stranded on a lying
        panel. The launch really went launching → running while help was up; the
        poll is the only thing that can notice, so it has to still be alive."""
        out = self.cover_the_launch(4000, self.RESOLVED)
        panel = out["liveAfterClose"]["launch"] or ""
        self.assertIn("● LIVE", panel,
                      "the restored panel must show the resolved launch: " + panel)
        self.assertNotIn("Launching the app…", panel,
                         "the panel must not still claim the launch is in flight")

    def test_the_launch_poll_survives_the_cover(self):
        out = self.cover_the_launch(4000, self.RESOLVED)
        self.assertIn("● LIVE", out["liveUnderCover"]["launch"] or "",
                      "the poll must resolve the launch while still covered")

    # ── nothing the first fix round earned is given back ──

    def test_the_covered_console_is_the_only_thing_hidden(self):
        """Help is still the ONE console on the stage while it is up — the cover
        hides its charge, it does not leave two consoles on screen."""
        out = self.over_file(keys=[{"key": "Escape"}])
        self.assertEqual(out["stageAtHelp"]["modals"], ["modal wide help-console"])
        self.assertEqual(out["stageAtHelp"]["textareas"], [],
                         "the covered console must not be on screen at all")

    def over_file(self, **spec):
        cf = {"kind": "file", "type": "warp core coolant is leaking"}
        cf.update(spec.pop("console", {}))
        return self.open_help("key", consoleFirst=cf, **spec)


# ══════════ 10. the view-only line, MEASURED ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class ViewOnlyOpenersMeasuredTest(HelpBase):
    """D-B — the second wording of this line was wrong too. "open any console the
    briefing names" is false for five of the six: markViewOnly() disables
    #deployMainBtn and every .board .btn.go/.warn/.danger, and those ARE the
    console openers. Only ▦ File Mission survives.

    String-matching a preferred phrase would let a third wrong wording through,
    so this MEASURES: it drives a real read-only board, reads the disabled state
    off every opener the briefing names, and holds the line to it. Nothing here
    asks markViewOnly or applyWriteState to change — the guard is right, the
    words were wrong."""

    # The surfaces you reach from the board itself. Controls that live INSIDE a
    # console (its foot buttons, its fields) are not openers — you are already
    # through the door by then.
    OPENER_SURFACES = ("band", "board")

    def measured(self):
        out = self.open_help("key", brd=full_board(), readonly=True,
                             missionDetail=VERIFY_DETAIL, resolveRefs=True)
        openers = {}
        for ref in out["refs"]:
            if ref["surface"] in self.OPENER_SURFACES:
                self.assertTrue(ref["labelled"],
                                "the briefing names %r but nothing on the %s "
                                "carries it" % (ref["label"], ref["surface"]))
                openers[ref["label"]] = ref["disabled"]
        return out["help"]["viewOnlyNote"], openers

    def test_the_measurement_reproduces_the_testers_table(self):
        """Ground truth, stated once so the assertions below mean something: on a
        view-only board the File console is the ONE thing the briefing names that
        still opens. Everything else is disabled where it stands."""
        _, openers = self.measured()
        live = sorted(k for k, dead in openers.items() if not dead)
        dead = sorted(k for k, d in openers.items() if d)
        self.assertEqual(live, ["▦ File Mission"])
        self.assertEqual(dead, sorted(["▹ START ALIGNMENT", "▶ Start", "⏸ Pause",
                                       "▶ Resume", "Answer ▸", "✓ Review PR ▸",
                                       "▸ Deploy Main"]))

    def test_the_line_names_every_control_that_really_still_opens(self):
        line, openers = self.measured()
        for label, dead in sorted(openers.items()):
            if not dead:
                self.assertIn(label, line,
                              "%s DOES still open on a view-only board — the "
                              "line must say so: %s" % (label, line))

    def test_the_line_raises_no_control_that_is_disabled(self):
        line, openers = self.measured()
        for label, dead in sorted(openers.items()):
            if dead:
                self.assertNotIn(label, line,
                                 "%s does not open on a view-only board — the "
                                 "line must not offer it: %s" % (label, line))

    def test_the_line_makes_no_blanket_promise_about_consoles(self):
        """The exact shape of both wrong versions: a universal claim over a set
        that is mostly disabled. Any 'any / every / all console' phrasing is a
        lie the moment one opener is gated."""
        line, openers = self.measured()
        self.assertTrue(any(openers.values()),
                        "precondition: some named opener IS disabled")
        self.assertIsNone(
            re.search(r"\b(any|every|all)\s+consoles?\b", line, re.I),
            "a blanket console promise cannot be true here: " + line)

    def test_the_line_says_the_disabled_controls_are_disabled(self):
        line, _ = self.measured()
        self.assertRegex(line.lower(), r"disabled",
                         "the majority case — controls dead where they stand — "
                         "must be stated: " + line)

    def test_the_line_says_the_board_stays_readable(self):
        line, _ = self.measured()
        self.assertRegex(line.lower(), r"read")

    def test_the_line_is_one_line_not_a_paragraph(self):
        line, _ = self.measured()
        self.assertLessEqual(len(line), 260,
                             "this is one line in a briefing: " + line)

    def test_the_code_comment_above_the_line_is_not_the_old_false_claim(self):
        """The comment justifying the copy asserted the openers are NOT disabled —
        the very thing measured false above. A wrong comment re-breeds the wrong
        copy."""
        with open(os.path.join(STATIC, "board.js")) as fh:
            src = fh.read()
        self.assertNotIn("the other console-openers are NOT disabled", src)


# ══════════ 11. one `s` label, two card states ══════════

@unittest.skipUnless(NODE, "node is required for the board.js vm harness")
class StartLabelBothCardStatesTest(HelpBase):
    """D-C — the deck said `s` opens "the launch console". True on a holding card;
    on a STANDBY card the same data-act=start control is ▹ START ALIGNMENT and
    opens the Alignment Console instead. One key, one printed label, two
    destinations — so the label has to be honest about both."""

    def cards(self):
        brd = board({"align": [mission("hold"), mission("park", prdPending=True)]})
        out = self.run_board(brd)
        return {c["mid"]: c for c in out["cards"]}, out

    def starts(self):
        cards, out = self.cards()
        got = {}
        for mid, card in cards.items():
            hits = [a["text"] for a in card["acts"] if a["act"] == "start"]
            self.assertEqual(len(hits), 1,
                             "%s must render exactly one start control" % mid)
            got[mid] = hits[0]
        return got, {b["id"]: b for b in out["bindings"]}["start"]["label"]

    def test_the_same_start_identity_carries_two_different_controls(self):
        """Ground truth: `s` resolves data-act=start on whichever card holds
        focus, and the two card states put different buttons there."""
        got, _ = self.starts()
        self.assertEqual(got["hold"], "▶ Start")
        self.assertEqual(got["park"], "▹ START ALIGNMENT")

    def test_the_label_does_not_name_the_launch_console(self):
        _, label = self.starts()
        self.assertIsNone(re.search(r"\blaunch\b", label, re.I),
                          "a standby card's `s` opens the Alignment Console, not "
                          "the launch console: " + label)

    def test_the_label_does_not_name_the_alignment_console_either(self):
        """Guard on the guard: swapping one wrong console name for the other is
        not the fix."""
        _, label = self.starts()
        self.assertIsNone(re.search(r"\balign(ment)?\b", label, re.I),
                          "naming Alignment would lie on a holding card: " + label)

    def test_the_label_still_says_it_opens_a_console(self):
        _, label = self.starts()
        self.assertTrue(label.lower().startswith("open"), label)
        self.assertIn("console", label.lower())

    def test_the_label_still_points_at_the_focused_mission(self):
        _, label = self.starts()
        self.assertRegex(label.lower(), r"focused")

    def test_the_cheatsheet_prints_the_one_honest_label(self):
        """One label, rendered verbatim — fixing it fixes the deck."""
        out = self.open_help("key")
        rows = {b["id"]: r for r, b in zip(out["help"]["rows"], out["bindings"])}
        self.assertEqual(rows["start"]["caps"], ["s"])
        self.assertIsNone(re.search(r"\blaunch\b", rows["start"]["label"], re.I))


# ══════════ 12. the deck's rhythm: every row the same height ══════════

class DeckRowRhythmTest(unittest.TestCase):
    """D-D — the keycap gutter is a fixed 110px while Enter + Space + the 5px gap
    need 114px, so that ONE row wrapped and stood 66px tall against 36px for
    every other row. The deck reads as a table; a row that breaks the grid reads
    as a fault.

    The gutter is pinned by MEASUREMENT, not by a magic number: the cap width is
    computed from the shipping `.help-console kbd` rule, and the model is itself
    pinned against the browser figure the tester measured (Enter = 54.5px)."""

    def setUp(self):
        with open(os.path.join(STATIC, "board.css")) as fh:
            self.css = fh.read()
        with open(os.path.join(HERE, "..", "static", "board.js")) as fh:
            self.js = fh.read()

    def rule(self, sel):
        i = self.css.index(sel)
        return self.css[self.css.index("{", i) + 1:self.css.index("}", i)]

    def num(self, rule, pattern):
        m = re.search(pattern, rule)
        self.assertIsNotNone(m, "missing %r in %r" % (pattern, rule))
        return float(m.group(1))

    def cap_width(self, text):
        """One <kbd>, in CSS pixels, from the shipping rule. --font-mono is a
        monospace face: advance ≈ 0.6em, plus the declared tracking, plus the
        rule's own horizontal padding and border."""
        kbd = self.rule(".help-console kbd")
        size = self.num(kbd, r"font-size:(\d+(?:\.\d+)?)px")
        track = self.num(kbd, r"letter-spacing:(\.?\d+(?:\.\d+)?)em")
        pad = self.num(kbd, r"padding:\d+(?:\.\d+)?px (\d+(?:\.\d+)?)px")
        border = self.num(kbd, r"border:(\d+(?:\.\d+)?)px")
        return len(text) * size * (0.6 + track) + 2 * pad + 2 * border

    def gutter(self):
        """The width the caps column is held to, however it is declared."""
        caps = self.rule(".help-console .keycaps")
        m = (re.search(r"min-width:(\d+(?:\.\d+)?)px", caps)
             or re.search(r"flex:\s*\d+\s+\d+\s+(\d+(?:\.\d+)?)px", caps)
             or re.search(r"\bwidth:(\d+(?:\.\d+)?)px", caps))
        self.assertIsNotNone(m, "the keycaps gutter declares no width: " + caps)
        return float(m.group(1))

    def widest_row(self):
        """The widest cap SET any binding actually prints, read off board.js's
        KEY_BINDINGS — so a future binding with a longer cap fails this suite
        instead of quietly wrapping in the shipped console."""
        caps = self.rule(".help-console .keycaps")
        gap = self.num(caps, r"gap:(\d+(?:\.\d+)?)px")
        rows = re.findall(r"keys:\s*\[([^\]]*)\]", self.js)
        self.assertTrue(rows, "no KEY_BINDINGS keycaps found in board.js")
        widest, which = 0.0, None
        for row in rows:
            keys = re.findall(r'"([^"]*)"', row)
            if not keys:
                continue
            w = sum(self.cap_width(k) for k in keys) + gap * (len(keys) - 1)
            if w > widest:
                widest, which = w, keys
        return widest, which

    def test_the_width_model_matches_the_browser(self):
        """Pin the model itself: the tester measured Enter at 54.5px in Chrome."""
        self.assertAlmostEqual(self.cap_width("Enter"), 54.5, delta=1.0)

    def test_the_widest_row_of_keycaps_fits_the_gutter(self):
        widest, which = self.widest_row()
        self.assertGreaterEqual(
            self.gutter(), widest,
            "the %r row needs %.1fpx of gutter but gets %.1fpx — it wraps, and a "
            "wrapped row stands twice as tall as every other row in the deck"
            % (which, widest, self.gutter()))

    def test_the_gutter_leaves_room_for_a_binding_not_written_yet(self):
        """A gutter that only just fits today breaks on the next binding. Keep
        real headroom — about another keycap's worth."""
        widest, _ = self.widest_row()
        self.assertGreaterEqual(
            self.gutter() - widest, 30,
            "only %.1fpx spare: the next binding with a long cap wraps the row"
            % (self.gutter() - widest))

    def test_the_keycap_gutter_cannot_wrap_at_all(self):
        """Belt to the braces: whatever the arithmetic, the gutter must not be
        allowed to break onto a second line — that break IS the defect."""
        caps = self.rule(".help-console .keycaps")
        self.assertIn("flex-wrap:nowrap", caps.replace(" ", ""),
                      "a wrapping keycap gutter makes that row taller than the "
                      "rest of the deck: " + caps)

    def test_the_keycap_still_wears_the_font_that_disambiguates_l(self):
        """D5's legibility win is not paid for with this fix."""
        self.assertIn("var(--font-mono)", self.rule(".help-console kbd"))


if __name__ == "__main__":
    unittest.main()
